class Bank {
    private long[] balance;
    private int n;

    public Bank(long[] balance) {
        this.balance = balance;
        this.n = balance.length;
    }

    private boolean validAccount(int account) {
        return account >= 1 && account <= n;
    }

    public boolean transfer(int account1, int account2, long money) {
        if (!validAccount(account1) || !validAccount(account2)) return false;
        if (balance[account1 - 1] < money) return false;
        balance[account1 - 1] -= money;
        balance[account2 - 1] += money;
        return true;
    }

    public boolean deposit(int account, long money) {
        if (!validAccount(account)) return false;
        balance[account - 1] += money;
        return true;
    }

    public boolean withdraw(int account, long money) {
        if (!validAccount(account)) return false;
        if (balance[account - 1] < money) return false;
        balance[account - 1] -= money;
        return true;
    }
}

import java.util.*;

class Bank {
    private Map<Integer, Long> accounts;

    public Bank(long[] balance) {
        accounts = new HashMap();
        for (int i = 0; i < balance.length; i++) {
            accounts.put(i + 1, balance[i]);
        }
    }

    public boolean transfer(int account1, int account2, long money) {
        if (!accounts.containsKey(account1) || !accounts.containsKey(account2)) return false;
        long bal1 = accounts.get(account1).longValue();
        if (bal1 < money) return false;
        accounts.put(account1, bal1 - money);
        accounts.put(account2, accounts.get(account2).longValue() + money);
        return true;
    }

    public boolean deposit(int account, long money) {
        if (!accounts.containsKey(account)) return false;
        accounts.put(account, accounts.get(account).longValue() + money);
        return true;
    }

    public boolean withdraw(int account, long money) {
        if (!accounts.containsKey(account)) return false;
        long bal = accounts.get(account).longValue();
        if (bal < money) return false;
        accounts.put(account, bal - money);
        return true;
    }
}
